pous.declaration:
FUNCTION_BLOCK StarDelta
VAR_INPUT
    start : BOOL;
    stop : BOOL;
    overload : BOOL;
END_VAR
VAR_OUTPUT
    mainContactor : BOOL;
    starContactor : BOOL;
    deltaContactor : BOOL;
END_VAR
VAR
    stage : INT := 0;
    startPrev : BOOL;
    startEdge : BOOL;
    starTon : TON;
END_VAR

pous.implementation:
startEdge := start AND NOT startPrev;
startPrev := start;
IF stop OR overload THEN
    stage := 0;
    mainContactor := FALSE;
    starContactor := FALSE;
    deltaContactor := FALSE;
    starTon(IN := FALSE, PT := T#5s);
ELSIF startEdge THEN
    stage := 1;
    mainContactor := TRUE;
    starContactor := TRUE;
    deltaContactor := FALSE;
END_IF
IF stage = 1 THEN
    starTon(IN := TRUE, PT := T#5s);
    IF starTon.Q THEN
        stage := 2;
        starContactor := FALSE;
        deltaContactor := TRUE;
    END_IF
END_IF
